// ============================================================
// TEMPLATE LIBRARY — Social Posts
// Each template is a function that returns HTML given fields + theme + format
// ============================================================

function escapeHtml(s){
  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function nl2br(s){ return escapeHtml(s).replace(/\n/g,'<br>'); }

// Standard wrapper for social posts - sets canvas dimensions
function socialFrame(content, theme, fmt, opts={}){
  const fmtCfg = FORMATS[fmt];
  let bgLayer = '';
  if(opts.bgImage){
    const fx = (opts.bgFocalX != null ? opts.bgFocalX : 50);
    const fy = (opts.bgFocalY != null ? opts.bgFocalY : 50);
    const zoom = (opts.bgZoom != null ? opts.bgZoom : 100);
    const opacity = (opts.bgOpacity != null ? opts.bgOpacity : 100) / 100;
    // background-size goes from cover (100%) up to N% of cover (zoom in further)
    const sizeVal = zoom <= 100 ? 'cover' : `${zoom}% auto`;
    // Edge case: if image's natural aspect doesn't match cover at exact zoom,
    // use max(width%, height%) to ensure no white edges
    bgLayer = `<div style="position:absolute;inset:0;background-image:url('${opts.bgImage}');background-size:${sizeVal};background-position:${fx}% ${fy}%;background-repeat:no-repeat;opacity:${opacity};pointer-events:none;"></div>`;
  }
  return `<div style="width:${fmtCfg.w}px;height:${fmtCfg.h}px;background:${theme.bg};position:relative;font-family:'Lato',sans-serif;color:${theme.text};overflow:hidden;">${bgLayer}<div style="position:absolute;inset:0;">${content}</div></div>`;
}

function logoMark(theme, size=56){
  const isDark = ['deep','midnight'].includes(theme.id);
  const choice = (typeof state !== 'undefined' && state.logoChoice) ? state.logoChoice : 'icon-png';
  if(typeof state !== 'undefined' && state.logoScale != null) size = size * state.logoScale;

  // Custom uploaded logo
  if(choice === 'custom' && typeof state !== 'undefined' && state.logoCustom){
    return `<img src="${state.logoCustom}" style="height:${size}px;width:auto;max-width:${size*2}px;object-fit:contain;display:inline-block;vertical-align:middle;">`;
  }

  // Built-in PNG options (default to icon-png if nothing else matches)
  const preset = LOGO_PRESETS.find(p=>p.id===choice) || LOGO_PRESETS[0];
  const url = isDark ? preset.light : preset.dark;
  const w = Math.round(size * preset.aspect);
  return `<img src="${url}" style="width:${w}px;height:${size}px;object-fit:contain;display:inline-block;vertical-align:middle;">`;
}

