// ============================================================
// NEWSLETTER TEMPLATES
// ============================================================

function newsletterFrame(blocks, theme, opts={}){
  // For newsletter, we use a fixed 600px wide format with auto height.
  // Background applies to the OUTER container; content sits in a relative layer above it.
  let bgLayer = '';
  if(opts.bgImage){
    const fx = (opts.bgFocalX != null ? opts.bgFocalX : 50);
    const fy = (opts.bgFocalY != null ? opts.bgFocalY : 50);
    const zoom = (opts.bgZoom != null ? opts.bgZoom : 100);
    const opacity = (opts.bgOpacity != null ? opts.bgOpacity : 100) / 100;
    const sizeVal = zoom <= 100 ? 'cover' : `${zoom}% auto`;
    // Newsletter bg uses fixed attachment-like effect (image positioned across full height)
    bgLayer = `<div style="position:absolute;inset:0;background-image:url('${opts.bgImage}');background-size:${sizeVal};background-position:${fx}% ${fy}%;background-repeat:no-repeat;opacity:${opacity};pointer-events:none;z-index:0;"></div>`;
  }
  return `<div style="width:600px;background:${theme.bg};font-family:'Lato',sans-serif;color:${theme.text};overflow:hidden;position:relative;">${bgLayer}<div style="position:relative;z-index:1;">${blocks}</div></div>`;
}

function nlHeader(theme, fields){
  const showLogo  = fields._show_logo  !== false;
  const showName  = fields._show_name  !== false;
  const showIssue = fields._show_issue !== false;
  if(!showLogo && !showName && !showIssue) return '';
  return `
    <div style="background:${theme.surface};padding:40px 40px 30px;text-align:center;border-bottom:1px solid ${theme.subtle};">
      ${showLogo  ? `<div style="width:64px;height:64px;margin:0 auto 16px;display:flex;align-items:center;justify-content:center;">${logoMark(theme, 64)}</div>` : ''}
      ${showName  ? `<div style="font-family:'Playfair Display',serif;font-weight:600;font-size:24px;color:${theme.text};letter-spacing:-0.01em;font-variation-settings:'opsz' 48;">${escapeHtml(fields.publication_name || 'Fredheim Livsstilssenter')}</div>` : ''}
      ${showIssue ? `<div style="font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:0.2em;color:${theme.accent};margin-top:6px;text-transform:uppercase;">${escapeHtml(fields.issue_label || 'Utgave 01 · Helsebrevet')}</div>` : ''}
    </div>
  `;
}

function nlFooter(theme, fields){
  const showTagline = fields._show_tagline !== false;
  const showContact = fields._show_contact !== false;
  const showLinks   = fields._show_links   !== false;
  if(!showTagline && !showContact && !showLinks) return '';
  const websiteUrl      = fields.website_url       || 'https://fredheim.org';
  const unsubUrl        = fields.unsub_url         || '#';
  const websiteLinkText = fields.website_link_text || 'Besøk nettsiden';
  const unsubLinkText   = fields.unsub_link_text   || 'Avmeld';
  return `
    <div style="background:${theme.surface};padding:30px 40px;text-align:center;border-top:1px solid ${theme.subtle};">
      ${showTagline ? `<div style="font-family:'Playfair Display',serif;font-style:italic;font-size:14px;color:${theme.accent};margin-bottom:14px;">${escapeHtml(fields.tagline || 'Helse for kropp, sinn og sjel')}</div>` : ''}
      ${showContact ? `<div style="font-size:11px;color:${theme.muted};line-height:1.7;">Fredheim Livsstilssenter · ${escapeHtml(fields.email || 'post@fredheim.org')}${showLinks ? '<br>' : ''}</div>` : ''}
      ${showLinks   ? `<div style="font-size:11px;color:${theme.muted};line-height:1.7;"><a href="${escapeHtml(websiteUrl)}" style="color:${theme.accent};text-decoration:none;">${escapeHtml(websiteLinkText)}</a> · <a href="${escapeHtml(unsubUrl)}" style="color:${theme.accent};text-decoration:none;">${escapeHtml(unsubLinkText)}</a></div>` : ''}
    </div>
  `;
}

// Helper: render an inline image block within a newsletter
// img can be a string (url) or {url, align, widthPct, caption}
function renderImageBlock(img, theme){
  if(!img) return '';
  const url = typeof img === 'string' ? img : img.url;
  if(!url) return '';
  const align = (img.align || 'center');
  const widthPct = +(img.widthPct || 100);
  const caption = (img.caption || '').trim();
  const alignCss = align === 'left' ? 'left' : (align === 'right' ? 'right' : 'center');
  const margin = align === 'center' ? '0 auto' : (align === 'right' ? '0 0 0 auto' : '0 auto 0 0');
  return `
    <div style="padding:8px 40px;text-align:${alignCss};">
      <img src="${url}" alt="" style="display:block;max-width:${widthPct}%;height:auto;margin:${margin};border-radius:6px;" />
      ${caption ? `<div style="font-size:12px;color:${theme.muted};font-style:italic;margin-top:8px;text-align:${alignCss};">${escapeHtml(caption)}</div>` : ''}
    </div>
  `;
}

// Helper: render a CTA button row (single button) with real href
function renderCtaButton(text, url, theme, opts){
  opts = opts || {};
  const align = opts.align || 'center';
  const style = opts.style || 'primary';
  const onDark = ['deep','midnight'].includes(theme.id);
  const fg = style === 'primary' ? (onDark ? '#1A3D28' : '#FFFFFF') : theme.accent;
  const bg = style === 'primary' ? theme.accent : 'transparent';
  const border = style === 'primary' ? bg : theme.accent;
  const href = (url && url.trim()) ? url.trim() : '#';
  return `
    <div style="padding:0 40px 0;text-align:${align};">
      <a href="${escapeHtml(href)}" style="display:inline-block;padding:14px 28px;background:${bg};color:${fg};text-decoration:none;font-weight:700;font-size:14px;border-radius:8px;letter-spacing:0.02em;border:1.5px solid ${border};">${escapeHtml(text || 'Les mer →')}</a>
    </div>
  `;
}

// Render a single block of the Custom Newsletter
function renderCustomBlock(b, theme){
  if(!b || !b.type) return '';
  const align = b.align || 'left';
  if(b.type === 'heading'){
    const lvl = b.level || 'h2';
    const sizes = {h1:'34px', h2:'26px', h3:'20px', h4:'16px'};
    const fs = sizes[lvl] || '22px';
    return `<div style="padding:18px 40px 6px;text-align:${align};">
      <div style="font-family:'Playfair Display',serif;font-weight:700;font-size:${fs};line-height:1.15;color:${theme.text};letter-spacing:-0.02em;font-variation-settings:'opsz' 96;">${escapeHtml(b.text || '')}</div>
    </div>`;
  }
  if(b.type === 'text'){
    return `<div style="padding:8px 40px 14px;text-align:${align};">
      <div style="font-size:14.5px;line-height:1.7;color:${theme.muted};white-space:pre-wrap;">${nl2br(b.text || '')}</div>
    </div>`;
  }
  if(b.type === 'image'){
    return renderImageBlock(b, theme);
  }
  if(b.type === 'cta'){
    return `<div style="padding:14px 0 14px;">${renderCtaButton(b.text, b.url, theme, {align:align, style:b.style || 'primary'})}</div>`;
  }
  if(b.type === 'divider'){
    if(b.style === 'space'){
      return `<div style="padding:14px 40px;"></div>`;
    }
    return `<div style="padding:14px 40px;"><div style="height:1px;background:${theme.subtle};"></div></div>`;
  }
  return '';
}


