// ============================================================
// All templates registry
// ============================================================
const ALL_TEMPLATES = [
  TPL_wellness_tip, TPL_quote, TPL_promo, TPL_announce,
  TPL_photo_overlay, TPL_numbered, TPL_did_you_know, TPL_story, TPL_bts,
  TPL_nl_monthly, TPL_nl_roundup, TPL_nl_announce, TPL_nl_trip, TPL_nl_custom,
];

function getTemplate(id){ return ALL_TEMPLATES.find(t=>t.id===id); }

// ============================================================
// STATE
// ============================================================
let state = {
  mode: 'social',        // 'social' | 'newsletter'
  format: 'ig-square',
  templateId: 'wellness-tip',
  themeId: 'fredheim',
  fields: {},             // user-edited field values
  bgImage: null,          // bg image data URL (per-design)
  bgFocalX: 50,          // focal point % (0-100)
  bgFocalY: 50,
  bgZoom: 100,           // zoom % (100 = cover, 200 = 2x)
  bgOpacity: 100,        // opacity %
  logoChoice: 'icon-png',
  logoCustom: null,
  logoScale: 1,
  currentId: null,
  currentName: 'Untitled',
};

// Initialize fields with defaults from current template
function resetFieldsFromTemplate(){
  const tpl = getTemplate(state.templateId);
  if(!tpl) return;
  state.fields = {};
  tpl.fields.forEach(f=>{
    if(f.default !== undefined) {
      // Deep-copy non-primitive defaults so mutations (blocks, image_block) don't pollute template defaults
      const d = f.default;
      state.fields[f.key] = (d !== null && typeof d === 'object') ? JSON.parse(JSON.stringify(d)) : d;
    }
  });
}

// ============================================================
// STORAGE
// ============================================================
const STORAGE_KEY = 'fredheim_content_studio_v1';
const BG_LIBRARY_KEY = 'fredheim_bg_library_v1';

function loadAll(){
  try{ return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]'); }
  catch(e){ return []; }
}
function saveAll(items){ localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }

// ===== Persistent background library =====
function loadBgLibrary(){
  try{ return JSON.parse(localStorage.getItem(BG_LIBRARY_KEY) || '[]'); }
  catch(e){ return []; }
}
function saveBgLibrary(items){
  try{
    localStorage.setItem(BG_LIBRARY_KEY, JSON.stringify(items));
  }catch(e){
    // Likely quota exceeded
    toast('Storage full — remove a background to add more');
  }
}
function addBgToLibrary(dataUrl, name){
  const lib = loadBgLibrary();
  // Avoid duplicates
  if(lib.some(b=>b.url===dataUrl)) return;
  lib.unshift({
    id: 'bg'+Math.random().toString(36).slice(2,10),
    name: name || ('Background '+(lib.length+1)),
    url: dataUrl,
    added: Date.now(),
  });
  // Cap at 30 items to keep localStorage manageable
  if(lib.length > 30) lib.length = 30;
  saveBgLibrary(lib);
}
function removeBgFromLibrary(id){
  saveBgLibrary(loadBgLibrary().filter(b=>b.id!==id));
}

function uid(){ return 'd'+Math.random().toString(36).slice(2,10); }

function persistCurrent(name){
  const items = loadAll();
  const design = {
    id: state.currentId || uid(),
    name: name || state.currentName,
    mode: state.mode,
    format: state.format,
    templateId: state.templateId,
    themeId: state.themeId,
    fields: state.fields,
    bgImage: state.bgImage,
    bgFocalX: state.bgFocalX,
    bgFocalY: state.bgFocalY,
    bgZoom: state.bgZoom,
    bgOpacity: state.bgOpacity,
    logoChoice: state.logoChoice,
    logoCustom: state.logoCustom,
    logoScale: state.logoScale,
    updated: Date.now(),
  };
  const idx = items.findIndex(d=>d.id===design.id);
  if(idx>=0) items[idx] = design;
  else items.push(design);
  saveAll(items);
  state.currentId = design.id;
  state.currentName = design.name;
  renderSaved();
}

function loadDesign(id){
  const d = loadAll().find(x=>x.id===id);
  if(!d) return;
  state.currentId = d.id;
  state.currentName = d.name;
  state.mode = d.mode || 'social';
  state.format = d.format || 'ig-square';
  state.templateId = d.templateId;
  state.themeId = d.themeId || 'fredheim';
  state.fields = d.fields || {};
  state.bgImage = d.bgImage || null;
  state.bgFocalX = d.bgFocalX != null ? d.bgFocalX : 50;
  state.bgFocalY = d.bgFocalY != null ? d.bgFocalY : 50;
  state.bgZoom = d.bgZoom != null ? d.bgZoom : 100;
  state.bgOpacity = d.bgOpacity != null ? d.bgOpacity : 100;
  let lc = d.logoChoice || 'icon-png';
  if(lc === 'svg-mark') lc = 'icon-png';
  state.logoChoice = lc;
  state.logoCustom = d.logoCustom || null;
  state.logoScale = d.logoScale != null ? d.logoScale : 1;
  render();
  toast(`Loaded "${d.name}"`);
}

function deleteDesign(id){
  saveAll(loadAll().filter(d=>d.id!==id));
  if(state.currentId === id){
    newDesign();
  }
  renderSaved();
  toast('Deleted');
}

function newDesign(){
  state.currentId = null;
  state.currentName = 'Untitled';
  // Keep mode/format/theme/template but reset fields
  if(state.mode === 'newsletter'){
    state.templateId = 'nl-monthly';
    state.format = 'newsletter';
  } else {
    state.templateId = 'wellness-tip';
    state.format = 'ig-square';
  }
  state.bgImage = null;
  state.bgFocalX = 50;
  state.bgFocalY = 50;
  state.bgZoom = 100;
  state.bgOpacity = 100;
  resetFieldsFromTemplate();
  render();
}

// ============================================================
// RENDERING
// ============================================================

function el(tag, attrs={}, ...children){
  const e = document.createElement(tag);
  for(const k in attrs){
    if(k==='text') e.textContent = attrs[k];
    else if(k==='html') e.innerHTML = attrs[k];
    else if(k==='class') e.className = attrs[k];
    else if(k.startsWith('on')) e[k.toLowerCase()] = attrs[k];
    else e.setAttribute(k, attrs[k]);
  }
  children.flat().forEach(c=>{
    if(c == null) return;
    if(typeof c === 'string') e.appendChild(document.createTextNode(c));
    else e.appendChild(c);
  });
  return e;
}

function getTheme(){ return THEMES.find(t=>t.id===state.themeId) || THEMES[0]; }
function currentTemplate(){ return getTemplate(state.templateId); }

// ---- Canvas / preview ----
function renderCanvas(){
  const canvas = document.getElementById('canvas');
  const info = document.getElementById('canvas-info');
  const tpl = currentTemplate();
  const theme = getTheme();
  if(!tpl){ canvas.innerHTML = '<div style="padding:40px;color:#888">No template selected</div>'; return; }

  // Inject the bgImage into fields for templates that respect it
  const fieldsWithBg = Object.assign({}, state.fields, {
    _bgImage: state.bgImage,
    _bgFocalX: state.bgFocalX,
    _bgFocalY: state.bgFocalY,
    _bgZoom: state.bgZoom,
    _bgOpacity: state.bgOpacity,
  });
  const html = tpl.render(fieldsWithBg, theme, state.format);

  // Wrap the template in canvas-inner. This separates the visual size
  // (on the outer .canvas) from the native render size (on .canvas-inner).
  canvas.innerHTML = `<div class="canvas-inner">${html}</div>`;

  const fmtCfg = FORMATS[state.format];
  const previewArea = document.querySelector('.preview-area');
  const wrap = document.querySelector('.canvas-wrap');
  const innerEl = canvas.querySelector('.canvas-inner');
  const templateRoot = innerEl.firstElementChild;
  if(!templateRoot) return;

  // Native dimensions
  const actualW = fmtCfg.w;
  let actualH = fmtCfg.h;
  if(actualH === 'auto'){
    // Force layout to measure natural height of newsletter
    actualH = templateRoot.scrollHeight || templateRoot.offsetHeight || 800;
  }

  // Available space (preview area minus padding for format bar + info text)
  const previewStyles = window.getComputedStyle(previewArea);
  const padX = parseFloat(previewStyles.paddingLeft) + parseFloat(previewStyles.paddingRight);
  const padY = parseFloat(previewStyles.paddingTop) + parseFloat(previewStyles.paddingBottom);
  // Reserve space for format bar (~50) + canvas-info (~24) + gaps (~40)
  const reservedV = 130;

  const availW = Math.max(previewArea.clientWidth - padX - 4, 200);
  const availH = Math.max(previewArea.clientHeight - padY - reservedV, 200);

  // Scale to fit, capped at 1 (never upscale)
  const scale = Math.min(availW / actualW, availH / actualH, 1);

  // Outer canvas takes the SCALED dimensions (so layout matches visual size)
  canvas.style.width = (actualW * scale) + 'px';
  canvas.style.height = (actualH * scale) + 'px';

  // Inner holds the template at native size, visually scaled via transform
  innerEl.style.width = actualW + 'px';
  innerEl.style.height = actualH + 'px';
  innerEl.style.transform = `scale(${scale})`;

  // Remember scale for export
  canvas.dataset.scale = String(scale);

  info.textContent = `${fmtCfg.name} · ${actualW} × ${actualH === 'auto' ? 'auto' : actualH} px`;
}

// ---- Format bar ----
function renderFormatBar(){
  const bar = document.getElementById('format-bar');
  bar.innerHTML = '';

  // Only show format options relevant to current mode/template
  let formatList;
  if(state.mode === 'newsletter'){
    formatList = ['newsletter'];
  } else {
    const tpl = currentTemplate();
    formatList = tpl && tpl.formats ? tpl.formats : ['ig-square','ig-story','fb-landscape','fb-portrait'];
  }

  formatList.forEach(fid=>{
    const cfg = FORMATS[fid];
    const btn = el('button',{
      class:'format-btn'+(state.format===fid?' active':''),
      onclick:()=>{ state.format = fid; render(); }
    });
    // Icon
    const iconSvg = {
      'square':    '<rect x="3" y="3" width="18" height="18" rx="2"/>',
      'story':     '<rect x="7" y="3" width="10" height="18" rx="2"/>',
      'landscape': '<rect x="2" y="6" width="20" height="12" rx="2"/>',
      'portrait':  '<rect x="5" y="3" width="14" height="18" rx="2"/>',
      'mail':      '<path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/>',
    }[cfg.icon] || '';
    btn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${iconSvg}</svg> ${cfg.short}`;
    bar.appendChild(btn);
  });
}

// ---- Templates gallery ----
function renderTemplates(){
  const grid = document.getElementById('tpl-grid');
  grid.innerHTML = '';
  const templates = ALL_TEMPLATES.filter(t=>t.category === state.mode);
  const theme = getTheme();

  templates.forEach(tpl=>{
    const card = el('div',{
      class:'tpl-card'+(tpl.id===state.templateId?' selected':'')+(tpl.category==='newsletter'?' newsletter-card':''),
      onclick:()=>{
        state.templateId = tpl.id;
        // Reset fields to template defaults for clarity
        resetFieldsFromTemplate();
        // Pick a sensible default format if current doesn't apply
        if(tpl.formats && !tpl.formats.includes(state.format)){
          state.format = tpl.formats[0];
        }
        render();
      }
    });
    const preview = el('div',{class:'tpl-preview'});
    preview.innerHTML = tpl.preview(theme);
    const name = el('div',{class:'tpl-name', text:tpl.name});
    card.appendChild(preview);
    card.appendChild(name);
    grid.appendChild(card);
  });
}

// ---- Field editor ----
function renderFieldEditor(){
  const container = document.getElementById('field-editor');
  container.innerHTML = '';
  const tpl = currentTemplate();
  if(!tpl) return;

  tpl.fields.forEach(field=>{
    const group = el('div',{class:'field-group'});
    // Hide label for block_list — it has its own header
    if(field.type !== 'block_list'){
      group.appendChild(el('div',{class:'field-label', text:field.label}));
    }

    if(field.type === 'text' || field.type === 'url'){
      const input = el('input',{
        type:'text',
        placeholder: field.type === 'url' ? 'https://...' : '',
        value: state.fields[field.key] != null ? String(state.fields[field.key]) : '',
        oninput:(e)=>{ state.fields[field.key] = e.target.value; renderCanvas(); }
      });
      group.appendChild(input);

    } else if(field.type === 'textarea'){
      const ta = el('textarea',{
        oninput:(e)=>{ state.fields[field.key] = e.target.value; renderCanvas(); }
      });
      ta.value = state.fields[field.key] != null ? String(state.fields[field.key]) : '';
      group.appendChild(ta);

    } else if(field.type === 'toggle'){
      const wrap = el('div',{class:'toggle-row',style:'display:flex;align-items:center;gap:10px;padding:4px 0;'});
      const cb = el('input',{type:'checkbox', style:'width:auto;margin:0;'});
      cb.checked = state.fields[field.key] !== false;
      cb.onchange = (e)=>{ state.fields[field.key] = !!e.target.checked; renderCanvas(); };
      const lbl = el('span',{style:'font-size:13px;color:var(--bark);',text:'Visible'});
      wrap.appendChild(cb);
      wrap.appendChild(lbl);
      group.appendChild(wrap);

    } else if(field.type === 'image'){
      const label = el('label',{class:'file-label'});
      label.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg><span>Upload photo</span>';
      const input = el('input',{type:'file',accept:'image/*',class:'file-input'});
      input.onchange = (e)=>{
        const file = e.target.files[0];
        if(!file) return;
        const reader = new FileReader();
        reader.onload = ()=>{ state.fields[field.key] = reader.result; renderFieldEditor(); renderCanvas(); };
        reader.readAsDataURL(file);
      };
      label.appendChild(input);
      group.appendChild(label);
      if(state.fields[field.key]){
        const preview = el('div',{class:'file-preview',style:`background-image:url('${state.fields[field.key]}')`});
        const clear = el('button',{class:'file-clear',onclick:()=>{
          state.fields[field.key] = null; renderFieldEditor(); renderCanvas();
        }});
        clear.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
        preview.appendChild(clear);
        group.appendChild(preview);

        // Photo size slider
        const scaleKey = '_' + field.key + '_scale';
        const scaleVal = state.fields[scaleKey] != null ? state.fields[scaleKey] : 100;
        const scaleWrap = el('div',{style:'margin-top:8px;'});
        const scaleHead = el('div',{style:'display:flex;justify-content:space-between;font-size:11px;color:var(--stone);margin-bottom:4px;'});
        scaleHead.appendChild(el('span',{text:'Photo Size'}));
        const scaleDisplay = el('span',{style:'font-family:var(--f-mono);font-size:10px;color:var(--pebble);',text:scaleVal+'%'});
        scaleHead.appendChild(scaleDisplay);
        scaleWrap.appendChild(scaleHead);
        const scaleRange = el('input',{type:'range',min:'50',max:'200',value:String(scaleVal),style:'width:100%;accent-color:var(--fredheim-green);'});
        scaleRange.oninput = (e)=>{
          state.fields[scaleKey] = +e.target.value;
          scaleDisplay.textContent = e.target.value+'%';
          renderCanvas();
        };
        scaleWrap.appendChild(scaleRange);
        group.appendChild(scaleWrap);
      }

    } else if(field.type === 'image_block'){
      // Image with alignment + width + caption controls
      let v = state.fields[field.key];
      if(typeof v === 'string') v = {url:v, align:'center', widthPct:100, caption:''};
      v = v || {url:'', align:'center', widthPct:100, caption:''};
      state.fields[field.key] = v;

      // URL input
      const urlIn = el('input',{
        type:'text', placeholder:'Image URL (or upload below)',
        value: v.url || '',
        oninput:(e)=>{ v.url = e.target.value; renderCanvas(); }
      });
      group.appendChild(urlIn);

      // Upload (alternative to URL)
      const uploadLbl = el('label',{class:'file-label',style:'margin-top:6px;'});
      uploadLbl.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg><span>Upload instead</span>';
      const upIn = el('input',{type:'file',accept:'image/*',class:'file-input'});
      upIn.onchange = (e)=>{
        const file = e.target.files[0]; if(!file) return;
        const reader = new FileReader();
        reader.onload = ()=>{ v.url = reader.result; renderFieldEditor(); renderCanvas(); };
        reader.readAsDataURL(file);
      };
      uploadLbl.appendChild(upIn);
      group.appendChild(uploadLbl);

      if(v.url){
        // Alignment selector
        const alignRow = el('div',{style:'display:flex;gap:6px;margin-top:8px;'});
        ['left','center','right'].forEach(a=>{
          const btn = el('button',{
            class:'btn-mini' + (v.align === a ? ' active' : ''),
            style:'flex:1;text-transform:capitalize;',
            text:a,
            onclick:()=>{ v.align = a; renderFieldEditor(); renderCanvas(); }
          });
          alignRow.appendChild(btn);
        });
        group.appendChild(alignRow);

        // Width slider
        const widthWrap = el('div',{style:'margin-top:8px;'});
        const widthHead = el('div',{style:'display:flex;justify-content:space-between;font-size:11px;color:var(--stone);margin-bottom:4px;'});
        widthHead.appendChild(el('span',{text:'Width'}));
        const widthVal = el('span',{text:(v.widthPct||100) + '%'});
        widthHead.appendChild(widthVal);
        widthWrap.appendChild(widthHead);
        const widthRange = el('input',{type:'range',min:'30',max:'100',value:String(v.widthPct||100),style:'width:100%;'});
        widthRange.oninput = (e)=>{ v.widthPct = +e.target.value; widthVal.textContent = v.widthPct + '%'; renderCanvas(); };
        widthWrap.appendChild(widthRange);
        group.appendChild(widthWrap);

        // Caption
        const capIn = el('input',{
          type:'text', placeholder:'Caption (optional)', style:'margin-top:8px;',
          value: v.caption || '',
          oninput:(e)=>{ v.caption = e.target.value; renderCanvas(); }
        });
        group.appendChild(capIn);

        // Clear
        const clearBtn = el('button',{class:'btn-mini',style:'margin-top:8px;',text:'Remove image',
          onclick:()=>{ state.fields[field.key] = {url:'', align:'center', widthPct:100, caption:''}; renderFieldEditor(); renderCanvas(); }
        });
        group.appendChild(clearBtn);
      }

    } else if(field.type === 'block_list'){
      // The big one: editable list of blocks for custom newsletter
      group.appendChild(renderBlockListEditor(field, state.fields[field.key] || []));
    }

    container.appendChild(group);
  });
}

// --- Block list editor (for Custom Newsletter) ---
function renderBlockListEditor(field, blocks){
  const wrap = el('div',{class:'block-list-wrap'});
  const title = el('div',{style:'font-size:13px;font-weight:600;color:var(--bark);margin-bottom:10px;text-transform:uppercase;letter-spacing:0.08em;',text:'Blocks'});
  wrap.appendChild(title);

  const list = el('div',{class:'block-list'});
  blocks.forEach((b, idx)=>{
    list.appendChild(renderBlockEditor(field, blocks, b, idx));
  });
  wrap.appendChild(list);

  // Add-block buttons
  const addWrap = el('div',{class:'block-add-wrap',style:'margin-top:14px;padding-top:14px;border-top:1px dashed var(--sage-soft);'});
  addWrap.appendChild(el('div',{style:'font-size:11px;color:var(--stone);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.1em;',text:'Add a block'}));
  const btns = el('div',{style:'display:grid;grid-template-columns:1fr 1fr;gap:6px;'});
  const blockTypes = [
    {type:'heading', label:'+ Heading', defaults:{level:'h2', text:'New heading', align:'left'}},
    {type:'text',    label:'+ Text',    defaults:{text:'New paragraph...', align:'left'}},
    {type:'image',   label:'+ Image',   defaults:{url:'', align:'center', widthPct:100, caption:''}},
    {type:'cta',     label:'+ Button',  defaults:{text:'Click me', url:'https://fredheim.org', align:'center', style:'primary'}},
    {type:'divider', label:'+ Divider', defaults:{style:'line'}},
    {type:'divider', label:'+ Space',   defaults:{style:'space'}},
  ];
  blockTypes.forEach(bt=>{
    const b = el('button',{class:'btn-mini',text:bt.label,
      onclick:()=>{
        const newBlock = Object.assign({id:'b'+Math.random().toString(36).slice(2,8), type:bt.type}, bt.defaults);
        blocks.push(newBlock);
        state.fields[field.key] = blocks;
        renderFieldEditor(); renderCanvas();
      }
    });
    btns.appendChild(b);
  });
  addWrap.appendChild(btns);
  wrap.appendChild(addWrap);

  return wrap;
}

function renderBlockEditor(field, allBlocks, b, idx){
  const card = el('div',{class:'block-card',style:'background:var(--cream);border:1px solid var(--sage-soft);border-radius:8px;padding:10px;margin-bottom:8px;'});

  // Header row: type label + move/remove controls
  const header = el('div',{style:'display:flex;align-items:center;gap:6px;margin-bottom:8px;'});
  const typeLabels = {heading:'HEADING', text:'TEXT', image:'IMAGE', cta:'BUTTON', divider:'DIVIDER'};
  header.appendChild(el('div',{style:'flex:1;font-family:"JetBrains Mono",monospace;font-size:10px;letter-spacing:0.15em;color:var(--accent,var(--forest-mid));',text:typeLabels[b.type] || b.type.toUpperCase()}));
  const upBtn = el('button',{class:'block-ctrl',title:'Move up',text:'↑',
    onclick:()=>{ if(idx>0){ const t=allBlocks[idx-1]; allBlocks[idx-1]=allBlocks[idx]; allBlocks[idx]=t; renderFieldEditor(); renderCanvas(); } }
  });
  const dnBtn = el('button',{class:'block-ctrl',title:'Move down',text:'↓',
    onclick:()=>{ if(idx<allBlocks.length-1){ const t=allBlocks[idx+1]; allBlocks[idx+1]=allBlocks[idx]; allBlocks[idx]=t; renderFieldEditor(); renderCanvas(); } }
  });
  const rmBtn = el('button',{class:'block-ctrl block-ctrl-danger',title:'Remove',text:'✕',
    onclick:()=>{ allBlocks.splice(idx,1); renderFieldEditor(); renderCanvas(); }
  });
  header.appendChild(upBtn);
  header.appendChild(dnBtn);
  header.appendChild(rmBtn);
  card.appendChild(header);

  // Per-type fields
  if(b.type === 'heading'){
    const ti = el('input',{type:'text',value:b.text||'',placeholder:'Heading text',
      oninput:(e)=>{ b.text = e.target.value; renderCanvas(); }});
    card.appendChild(ti);
    const ctrlRow = el('div',{style:'display:flex;gap:6px;margin-top:6px;'});
    const lvlSel = el('select',{style:'flex:0 0 70px;',
      onchange:(e)=>{ b.level = e.target.value; renderCanvas(); }});
    ['h1','h2','h3','h4'].forEach(l=>{
      const o = el('option',{value:l,text:l.toUpperCase()});
      if((b.level||'h2')===l) o.selected = true;
      lvlSel.appendChild(o);
    });
    ctrlRow.appendChild(lvlSel);
    ['left','center','right'].forEach(a=>{
      const btn = el('button',{class:'btn-mini'+((b.align||'left')===a?' active':''),style:'flex:1;text-transform:capitalize;',text:a,
        onclick:()=>{ b.align = a; renderFieldEditor(); renderCanvas(); }});
      ctrlRow.appendChild(btn);
    });
    card.appendChild(ctrlRow);

  } else if(b.type === 'text'){
    const ta = el('textarea',{rows:'3',
      oninput:(e)=>{ b.text = e.target.value; renderCanvas(); }});
    ta.value = b.text || '';
    card.appendChild(ta);
    const alignRow = el('div',{style:'display:flex;gap:6px;margin-top:6px;'});
    ['left','center','right'].forEach(a=>{
      const btn = el('button',{class:'btn-mini'+((b.align||'left')===a?' active':''),style:'flex:1;text-transform:capitalize;',text:a,
        onclick:()=>{ b.align = a; renderFieldEditor(); renderCanvas(); }});
      alignRow.appendChild(btn);
    });
    card.appendChild(alignRow);

  } else if(b.type === 'image'){
    const urlIn = el('input',{type:'text',value:b.url||'',placeholder:'Image URL (or upload)',
      oninput:(e)=>{ b.url = e.target.value; renderCanvas(); }});
    card.appendChild(urlIn);
    const upLbl = el('label',{class:'file-label',style:'margin-top:6px;'});
    upLbl.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg><span>Upload instead</span>';
    const upIn = el('input',{type:'file',accept:'image/*',class:'file-input'});
    upIn.onchange = (e)=>{
      const f = e.target.files[0]; if(!f) return;
      const r = new FileReader();
      r.onload = ()=>{ b.url = r.result; renderFieldEditor(); renderCanvas(); };
      r.readAsDataURL(f);
    };
    upLbl.appendChild(upIn);
    card.appendChild(upLbl);
    if(b.url){
      const alignRow = el('div',{style:'display:flex;gap:6px;margin-top:8px;'});
      ['left','center','right'].forEach(a=>{
        const btn = el('button',{class:'btn-mini'+((b.align||'center')===a?' active':''),style:'flex:1;text-transform:capitalize;',text:a,
          onclick:()=>{ b.align = a; renderFieldEditor(); renderCanvas(); }});
        alignRow.appendChild(btn);
      });
      card.appendChild(alignRow);
      const wrap = el('div',{style:'margin-top:8px;'});
      const head = el('div',{style:'display:flex;justify-content:space-between;font-size:11px;color:var(--stone);margin-bottom:4px;'});
      head.appendChild(el('span',{text:'Width'}));
      const vSpan = el('span',{text:(b.widthPct||100)+'%'});
      head.appendChild(vSpan);
      wrap.appendChild(head);
      const range = el('input',{type:'range',min:'30',max:'100',value:String(b.widthPct||100),style:'width:100%;'});
      range.oninput = (e)=>{ b.widthPct = +e.target.value; vSpan.textContent = b.widthPct + '%'; renderCanvas(); };
      wrap.appendChild(range);
      card.appendChild(wrap);
      const capIn = el('input',{type:'text',value:b.caption||'',placeholder:'Caption (optional)',style:'margin-top:8px;',
        oninput:(e)=>{ b.caption = e.target.value; renderCanvas(); }});
      card.appendChild(capIn);
    }

  } else if(b.type === 'cta'){
    const txt = el('input',{type:'text',value:b.text||'',placeholder:'Button label',
      oninput:(e)=>{ b.text = e.target.value; renderCanvas(); }});
    card.appendChild(txt);
    const urlIn = el('input',{type:'text',value:b.url||'',placeholder:'https://...',style:'margin-top:6px;',
      oninput:(e)=>{ b.url = e.target.value; renderCanvas(); }});
    card.appendChild(urlIn);
    const ctrlRow = el('div',{style:'display:flex;gap:6px;margin-top:6px;'});
    const styleSel = el('select',{style:'flex:0 0 90px;',
      onchange:(e)=>{ b.style = e.target.value; renderCanvas(); }});
    [['primary','Primary'],['secondary','Outline']].forEach(([v,l])=>{
      const o = el('option',{value:v,text:l});
      if((b.style||'primary')===v) o.selected = true;
      styleSel.appendChild(o);
    });
    ctrlRow.appendChild(styleSel);
    ['left','center','right'].forEach(a=>{
      const btn = el('button',{class:'btn-mini'+((b.align||'center')===a?' active':''),style:'flex:1;text-transform:capitalize;',text:a,
        onclick:()=>{ b.align = a; renderFieldEditor(); renderCanvas(); }});
      ctrlRow.appendChild(btn);
    });
    card.appendChild(ctrlRow);

  } else if(b.type === 'divider'){
    const sel = el('select',{onchange:(e)=>{ b.style = e.target.value; renderCanvas(); }});
    [['line','Line'],['space','Empty space']].forEach(([v,l])=>{
      const o = el('option',{value:v,text:l});
      if((b.style||'line')===v) o.selected = true;
      sel.appendChild(o);
    });
    card.appendChild(sel);
  }

  return card;
}

// ---- Theme picker ----
function renderThemes(){
  ['theme-grid','theme-grid-m'].forEach(id=>{
    const grid = document.getElementById(id);
    if(!grid) return;
    grid.innerHTML = '';
    THEMES.forEach(theme=>{
      const card = el('div',{
        class:'theme-card'+(theme.id===state.themeId?' selected':''),
        style:`background:${theme.bg};color:${theme.text};`,
        onclick:()=>{ state.themeId = theme.id; render(); }
      });
      card.innerHTML = `
        <div class="theme-name">${theme.name}</div>
        <div class="theme-strip">
          <span style="background:${theme.text}"></span>
          <span style="background:${theme.accent}"></span>
          <span style="background:${theme.surface}"></span>
        </div>
      `;
      grid.appendChild(card);
    });
  });
}

// ---- Logo picker ----
function renderLogos(){
  ['logo-grid','logo-grid-m'].forEach((gridId, i)=>{
    const grid = document.getElementById(gridId);
    if(!grid) return;
    grid.innerHTML = '';
    const uploadId = i === 0 ? 'logo-upload' : 'logo-upload-m';

    // Built-in presets (all PNGs)
    LOGO_PRESETS.forEach(preset=>{
      const t = el('div',{
        class:'logo-thumb'+(state.logoChoice===preset.id && !state.logoCustom?' selected':''),
        title:preset.name,
        onclick:()=>{
          state.logoChoice = preset.id;
          state.logoCustom = null;
          render();
        }
      });
      // Show the dark variant by default in the picker (works on cream bg)
      t.innerHTML = `<img src="${preset.dark}" alt="${preset.name}">`;
      grid.appendChild(t);
    });

    // Custom upload
    const upload = el('div',{
      class:'logo-thumb logo-thumb-upload'+(state.logoChoice==='custom' && state.logoCustom?' selected':''),
      title:'Upload custom logo',
      onclick:()=>document.getElementById(uploadId).click(),
    });
    if(state.logoCustom){
      upload.innerHTML = `<img src="${state.logoCustom}" alt="Custom">`;
    } else {
      upload.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>';
    }
    grid.appendChild(upload);
  });
}

// ---- Background picker ----
function renderBackgrounds(){
  // Backgrounds work for both social and newsletter modes
  ['bg-section','bg-section-m'].forEach(sectionId=>{
    const section = document.getElementById(sectionId);
    if(!section) return;
    section.style.display = 'block';
  });

  const library = loadBgLibrary();

  ['bg-section','bg-section-m'].forEach((sectionId, i)=>{
    const section = document.getElementById(sectionId);
    if(!section) return;
    const uploadId = i === 0 ? 'bg-upload' : 'bg-upload-m';

    // Rebuild the entire section content (more dynamic than just the grid now)
    section.innerHTML = '';

    // Section title
    section.appendChild(el('div',{class:'section-title', text:'Background'}));

    // ----- "None" + Built-in presets -----
    section.appendChild(el('div',{class:'bg-subtitle', text:'Brand'}));
    const presetGrid = el('div',{class:'bg-grid'});

    // None
    const none = el('div',{class:'bg-thumb bg-thumb-none'+(!state.bgImage?' selected':''),
      text:'None',
      onclick:()=>{ state.bgImage = null; render(); }
    });
    presetGrid.appendChild(none);

    // Built-in presets
    BG_PRESETS.filter(p=>p.url).forEach(preset=>{
      const t = el('div',{
        class:'bg-thumb'+(state.bgImage===preset.url?' selected':''),
        title:preset.name,
        onclick:()=>{ state.bgImage = preset.url; resetBgAdjust(); render(); },
      });
      t.style.backgroundImage = `url("${preset.url}")`;
      grid_addLabel(t, preset.name);
      presetGrid.appendChild(t);
    });

    section.appendChild(presetGrid);

    // ----- My Library (user uploads) -----
    section.appendChild(el('div',{class:'bg-subtitle', text:'My Library', style:'margin-top:14px'}));

    const libGrid = el('div',{class:'bg-grid'});

    // Upload tile (always first)
    const upload = el('div',{class:'bg-thumb bg-thumb-upload',title:'Upload background',
      onclick:()=>document.getElementById(uploadId).click()
    });
    upload.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>';
    libGrid.appendChild(upload);

    if(library.length === 0){
      const empty = el('div',{class:'bg-empty', text:'Your uploads will appear here.'});
      libGrid.appendChild(empty);
    } else {
      library.forEach(bg=>{
        const t = el('div',{
          class:'bg-thumb'+(state.bgImage===bg.url?' selected':''),
          title:bg.name,
          onclick:()=>{ state.bgImage = bg.url; resetBgAdjust(); render(); },
        });
        t.style.backgroundImage = `url("${bg.url}")`;

        const del = el('button',{class:'bg-thumb-delete', title:'Remove',
          onclick:(e)=>{
            e.stopPropagation();
            if(state.bgImage === bg.url) state.bgImage = null;
            removeBgFromLibrary(bg.id);
            render();
            toast('Removed from library');
          }
        });
        del.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
        t.appendChild(del);
        libGrid.appendChild(t);
      });
    }

    section.appendChild(libGrid);

    // ----- Adjustment controls (only when bg is active) -----
    if(state.bgImage){
      const adjustWrap = el('div',{class:'bg-adjust'});
      adjustWrap.appendChild(el('div',{class:'bg-subtitle',text:'Adjust', style:'margin-top:18px'}));

      // Opacity
      adjustWrap.appendChild(buildSlider({
        label:'Opacity',
        value:state.bgOpacity,
        min:10, max:100, unit:'%',
        onChange:(v)=>{ state.bgOpacity = v; renderCanvas(); syncBgSliders(); }
      }));

      // Zoom
      adjustWrap.appendChild(buildSlider({
        label:'Zoom',
        value:state.bgZoom,
        min:100, max:250, unit:'%',
        onChange:(v)=>{ state.bgZoom = v; renderCanvas(); syncBgSliders(); }
      }));

      // Focal X
      adjustWrap.appendChild(buildSlider({
        label:'Position X',
        value:state.bgFocalX,
        min:0, max:100, unit:'%',
        onChange:(v)=>{ state.bgFocalX = v; renderCanvas(); syncBgSliders(); }
      }));

      // Focal Y
      adjustWrap.appendChild(buildSlider({
        label:'Position Y',
        value:state.bgFocalY,
        min:0, max:100, unit:'%',
        onChange:(v)=>{ state.bgFocalY = v; renderCanvas(); syncBgSliders(); }
      }));

      // Reset button
      const reset = el('button',{class:'btn-mini', text:'Reset adjustments',
        onclick:()=>{ resetBgAdjust(); render(); toast('Reset'); }
      });
      adjustWrap.appendChild(reset);

      section.appendChild(adjustWrap);
    }

    // Re-add the hidden file input (it gets wiped by innerHTML reset)
    const fileInput = el('input',{type:'file',accept:'image/*',class:'file-input',id:uploadId});
    fileInput.onchange = handleBgUpload;
    section.appendChild(fileInput);
  });
}

// Helper to attach a small caption to a thumbnail
function grid_addLabel(thumb, name){
  const label = el('div',{class:'bg-thumb-label', text:name});
  thumb.appendChild(label);
}

// Reset bg adjustments
function resetBgAdjust(){
  state.bgFocalX = 50;
  state.bgFocalY = 50;
  state.bgZoom = 100;
  state.bgOpacity = 100;
}

// Sync slider values between desktop/mobile mirrored controls
function syncBgSliders(){
  // Both copies of renderBackgrounds use the same slider IDs would conflict;
  // simpler: just re-render so all slider values reflect current state
  // (only when user lets go - here we just update the displayed value)
}

// Build a slider control row
function buildSlider({label, value, min, max, unit, onChange}){
  const wrap = el('div',{class:'slider-row'});
  const head = el('div',{class:'slider-head'});
  head.appendChild(el('span',{class:'slider-label',text:label}));
  const valEl = el('span',{class:'slider-value',text:value+unit});
  head.appendChild(valEl);
  wrap.appendChild(head);

  const range = el('input',{type:'range', min:String(min), max:String(max), value:String(value)});
  range.oninput = (e)=>{
    const v = +e.target.value;
    valEl.textContent = v+unit;
    onChange(v);
  };
  wrap.appendChild(range);
  return wrap;
}

// Shared bg upload handler (used by both desktop and mobile inputs)
function handleBgUpload(e){
  const file = e.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = ()=>{
    // Add to persistent library
    const name = file.name.replace(/\.[^.]+$/, '').slice(0, 30) || 'Background';
    addBgToLibrary(reader.result, name);
    // Apply immediately
    state.bgImage = reader.result;
    resetBgAdjust();
    render();
    toast('Background added to library');
  };
  reader.readAsDataURL(file);
  e.target.value = '';
}

// ---- Saved designs ----
function renderSaved(){
  const items = loadAll().sort((a,b)=>b.updated-a.updated);
  ['saved-list','saved-list-m'].forEach(id=>{
    const list = document.getElementById(id);
    if(!list) return;
    list.innerHTML = '';
    if(items.length === 0){
      list.innerHTML = '<div style="font-size:11px;color:var(--pebble);font-style:italic;padding:6px;">Save designs to come back to them.</div>';
      return;
    }
    items.forEach(d=>{
      const item = el('div',{class:'saved-item'+(d.id===state.currentId?' active':''),
        onclick:()=>loadDesign(d.id)
      });
      const info = el('div',{class:'saved-info'});
      const tpl = getTemplate(d.templateId);
      info.appendChild(el('div',{class:'saved-name', text:d.name}));
      info.appendChild(el('div',{class:'saved-meta', text:`${tpl?tpl.name:'?'} · ${d.mode==='newsletter'?'Newsletter':FORMATS[d.format]?FORMATS[d.format].short:d.format}`}));
      item.appendChild(info);
      const del = el('button',{class:'icon-btn danger',onclick:(e)=>{
        e.stopPropagation();
        openDeleteModal(d);
      }});
      del.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg>';
      item.appendChild(del);
      list.appendChild(item);
    });
  });
}

// Main render orchestrator
function render(){
  renderFormatBar();
  renderTemplates();
  renderFieldEditor();
  renderThemes();
  renderLogos();
  renderBackgrounds();
  renderSaved();
  // Sync logo scale sliders to current state
  const scaleInt = Math.round(state.logoScale * 100);
  ['logo-scale-slider','logo-scale-slider-m'].forEach(id=>{
    const s = document.getElementById(id); if(s) s.value = scaleInt;
  });
  ['logo-scale-val','logo-scale-val-m'].forEach(id=>{
    const v = document.getElementById(id); if(v) v.textContent = scaleInt+'%';
  });
  // canvas needs to render after layout so dimensions are known
  setTimeout(renderCanvas, 0);
}

// ============================================================
// EXPORT
// ============================================================

async function exportPng(){
  toast('Exporting PNG...');
  const canvas = document.getElementById('canvas');
  const innerWrap = canvas.querySelector('.canvas-inner');
  if(!innerWrap) return;
  const templateRoot = innerWrap.firstElementChild;
  if(!templateRoot) return;

  // Temporarily remove the scale on the inner wrapper so html2canvas captures full resolution
  const origTransform = innerWrap.style.transform;
  innerWrap.style.transform = '';
  await new Promise(r=>setTimeout(r,80));

  const result = await html2canvas(templateRoot, {
    scale: 2,
    backgroundColor: null,
    useCORS: true,
    logging: false,
    width: templateRoot.scrollWidth,
    height: templateRoot.scrollHeight,
  });

  innerWrap.style.transform = origTransform;

  const link = document.createElement('a');
  link.download = `${(state.currentName||'design').replace(/[^a-z0-9]/gi,'_')}_${state.format}.png`;
  link.href = result.toDataURL('image/png');
  link.click();
  toast('PNG downloaded');
}

async function exportPdf(){
  toast('Building PDF...');
  const canvas = document.getElementById('canvas');
  const innerWrap = canvas.querySelector('.canvas-inner');
  if(!innerWrap) return;
  const templateRoot = innerWrap.firstElementChild;
  if(!templateRoot) return;

  const origTransform = innerWrap.style.transform;
  innerWrap.style.transform = '';
  await new Promise(r=>setTimeout(r,80));

  const result = await html2canvas(templateRoot, {
    scale: 2,
    backgroundColor: null,
    useCORS: true,
    logging: false,
  });

  innerWrap.style.transform = origTransform;

  const { jsPDF } = window.jspdf;
  const fmtCfg = FORMATS[state.format];
  const w = fmtCfg.w;
  const h = fmtCfg.h === 'auto' ? templateRoot.scrollHeight : fmtCfg.h;

  const pdf = new jsPDF({
    orientation: w > h ? 'landscape' : 'portrait',
    unit: 'px',
    format: [w, h],
  });
  pdf.addImage(result.toDataURL('image/png'), 'PNG', 0, 0, w, h);
  pdf.save(`${(state.currentName||'design').replace(/[^a-z0-9]/gi,'_')}.pdf`);
  toast('PDF downloaded');
}

// Generate email-safe HTML (table-based, inline styles)
function generateEmailHTML(){
  const tpl = currentTemplate();
  const theme = getTheme();
  if(!tpl || tpl.category !== 'newsletter') return '';

  // We'll wrap the existing render output in email-safe scaffolding
  // and replace web fonts with web-safe alternatives
  let inner = tpl.render(state.fields, theme);

  // Replace fonts: Manrope -> Helvetica/Arial, Fraunces -> Georgia, JetBrains Mono -> Courier
  inner = inner.replace(/'Lato'\s*,\s*sans-serif/g, "'Helvetica Neue', Arial, sans-serif");
  inner = inner.replace(/'Playfair Display'\s*,\s*serif/g, "Georgia, 'Times New Roman', serif");
  inner = inner.replace(/'JetBrains Mono'\s*,\s*monospace/g, "'Courier New', Courier, monospace");
  // Remove font-variation-settings which won't work in email
  inner = inner.replace(/font-variation-settings:[^;"']+;?/g, '');

  // Wrap in email-friendly template
  const email = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escapeHtml(state.fields.publication_name || 'Fredheim Livsstilssenter')}</title>
<style>
  body { margin:0; padding:0; background:${theme.bg}; }
  table { border-collapse:collapse; }
  img { border:0; display:block; }
  a { text-decoration:none; }
</style>
</head>
<body style="margin:0;padding:0;background:${theme.bg};font-family:'Helvetica Neue',Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${theme.bg};">
    <tr>
      <td align="center" style="padding:20px 10px;">
        <table width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background:${theme.bg};">
          <tr>
            <td>
              ${inner}
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

  return email;
}

async function exportEmailZip(){
  const html = generateEmailHTML();
  if(!html){ toast('Switch to Newsletter mode first'); return; }

  toast('Building ZIP…');

  const zip = new JSZip();
  let processed = html;
  let idx = 0;
  const extracted = [];

  // Find every base64 data-URL image and pull it out
  const re = /src="(data:(image\/[a-zA-Z+]+);base64,([^"]+))"/g;
  let m;
  while((m = re.exec(html)) !== null){
    const full     = m[1];                          // full data: URL
    const mime     = m[2];                          // e.g. image/png
    const b64      = m[3];                          // raw base64
    const ext      = mime.split('/')[1].replace('jpeg','jpg').replace('svg+xml','svg');
    const filename = `image-${++idx}.${ext}`;
    extracted.push({ filename, b64, mime });
    processed = processed.replace(full, `cid:${filename}`);
  }

  // Prepend a usage comment so it's clear how to wire CID attachments
  const note = extracted.length > 0
    ? `<!-- EMAIL PACKAGE\n     ${extracted.length} image(s) are included as separate files.\n     Attach each with Content-ID matching its filename, e.g.:\n       Content-Disposition: inline\n       Content-ID: <image-1.jpg>\n     Works with Outlook, Apple Mail, and email APIs (SendGrid, Mailgun, etc.).\n     For Mailchimp / hosted tools: upload images to your CDN and replace\n     the cid: references with their public URLs before pasting. -->\n`
    : '';
  processed = processed.replace('<!DOCTYPE html>', `<!DOCTYPE html>\n${note}`);

  zip.file('email.html', processed);
  extracted.forEach(img => zip.file(img.filename, img.b64, { base64: true }));

  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.download = `${(state.currentName || 'newsletter').replace(/[^a-z0-9]/gi, '_')}_email.zip`;
  a.href = URL.createObjectURL(blob);
  a.click();
  URL.revokeObjectURL(a.href);

  toast(extracted.length > 0
    ? `ZIP downloaded — ${extracted.length} image${extracted.length > 1 ? 's' : ''} as attachments`
    : 'ZIP downloaded (no embedded images found)');
}

function openExportModal(){
  const sub = document.getElementById('export-sub');
  const menu = document.getElementById('export-menu');
  menu.innerHTML = '';

  if(state.mode === 'newsletter'){
    sub.textContent = 'Choose how you want to use this newsletter.';
    addExportOption(menu, 'Email HTML', 'Copy/paste into Mailchimp, Gmail, etc.', 'mail', ()=>{
      const html = generateEmailHTML();
      document.getElementById('html-code').textContent = html;
      closeModal('modal-export');
      openModal('modal-html');
    });
    addExportOption(menu, 'Email + Images (ZIP)', 'Images as separate files — for API or desktop sending', 'zip', ()=>{
      closeModal('modal-export');
      exportEmailZip();
    });
    addExportOption(menu, 'PNG Image', 'For sharing as a preview or screenshot', 'image', ()=>{
      closeModal('modal-export');
      exportPng();
    });
    addExportOption(menu, 'PDF Document', 'Print-ready PDF version', 'file', ()=>{
      closeModal('modal-export');
      exportPdf();
    });
  } else {
    sub.textContent = 'Choose how you want to save this post.';
    addExportOption(menu, 'PNG Image', 'Ready to upload to Instagram, Facebook, etc.', 'image', ()=>{
      closeModal('modal-export');
      exportPng();
    });
    addExportOption(menu, 'PDF', 'For printing or archiving', 'file', ()=>{
      closeModal('modal-export');
      exportPdf();
    });
  }
  openModal('modal-export');
}

function addExportOption(menu, title, sub, icon, onclick){
  const icons = {
    mail:  '<path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/>',
    image: '<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/>',
    file:  '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/>',
    zip:   '<polyline points="21 8 21 21 3 21 3 8"/><rect x="1" y="3" width="22" height="5"/><line x1="10" y1="12" x2="14" y2="12"/><line x1="12" y1="10" x2="12" y2="14"/>',
  };
  const opt = el('div',{class:'export-option',onclick});
  opt.innerHTML = `
    <div class="export-option-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${icons[icon]||''}</svg></div>
    <div class="export-option-text">
      <div class="export-option-title">${title}</div>
      <div class="export-option-sub">${sub}</div>
    </div>
  `;
  menu.appendChild(opt);
}

// ============================================================
// MODALS & UTIL
// ============================================================
function openModal(id){ document.getElementById(id).classList.add('open'); }
function closeModal(id){ document.getElementById(id).classList.remove('open'); }

let toastTimer;
function toast(msg){
  const t = document.getElementById('toast');
  document.getElementById('toast-text').textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('show'), 2200);
}

let pendingDelete = null;
function openDeleteModal(d){
  pendingDelete = d.id;
  document.getElementById('delete-text').textContent = `"${d.name}" will be permanently removed.`;
  openModal('modal-delete');
}

// ============================================================
// EVENT WIRING
// ============================================================

// Mode switch
document.querySelectorAll('#mode-switch button').forEach(b=>{
  b.onclick = ()=>{
    state.mode = b.dataset.mode;
    document.querySelectorAll('#mode-switch button').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');
    if(state.mode === 'newsletter'){
      state.templateId = 'nl-monthly';
      state.format = 'newsletter';
    } else {
      state.templateId = 'wellness-tip';
      state.format = 'ig-square';
    }
    resetFieldsFromTemplate();
    render();
  };
});

// New
document.getElementById('btn-new').onclick = ()=>{
  if(confirm('Start fresh? Unsaved changes will be lost.')){
    newDesign();
  }
};

// Save
document.getElementById('btn-save').onclick = ()=>{
  document.getElementById('save-name-input').value = state.currentName === 'Untitled' ? '' : state.currentName;
  openModal('modal-save');
  setTimeout(()=>document.getElementById('save-name-input').focus(), 50);
};
document.getElementById('btn-confirm-save').onclick = ()=>{
  const name = document.getElementById('save-name-input').value.trim() || 'Untitled';
  persistCurrent(name);
  closeModal('modal-save');
  toast(`Saved "${name}"`);
};
document.getElementById('save-name-input').addEventListener('keydown',(e)=>{
  if(e.key==='Enter') document.getElementById('btn-confirm-save').click();
});

// Delete
document.getElementById('btn-confirm-delete').onclick = ()=>{
  if(pendingDelete){
    deleteDesign(pendingDelete);
    pendingDelete = null;
  }
  closeModal('modal-delete');
};

// Export
document.getElementById('btn-export').onclick = openExportModal;

// Copy HTML
document.getElementById('btn-copy-html').onclick = async ()=>{
  const html = document.getElementById('html-code').textContent;
  try{
    await navigator.clipboard.writeText(html);
    toast('HTML copied to clipboard');
  }catch(e){
    // Fallback
    const ta = document.createElement('textarea');
    ta.value = html;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    toast('HTML copied');
  }
};

// Logo scale sliders
['logo-scale-slider','logo-scale-slider-m'].forEach(id=>{
  const s = document.getElementById(id);
  if(!s) return;
  s.oninput = (e)=>{
    state.logoScale = +e.target.value / 100;
    // Sync both sliders + labels
    ['logo-scale-slider','logo-scale-slider-m'].forEach(sid=>{
      const el2 = document.getElementById(sid); if(el2 && el2 !== s) el2.value = e.target.value;
    });
    ['logo-scale-val','logo-scale-val-m'].forEach(vid=>{
      const v = document.getElementById(vid); if(v) v.textContent = e.target.value+'%';
    });
    renderCanvas();
  };
});

// Logo uploads (background uploads are wired inside renderBackgrounds)
['logo-upload','logo-upload-m'].forEach(id=>{
  const u = document.getElementById(id);
  if(u) u.onchange = (e)=>{
    const file = e.target.files[0];
    if(!file) return;
    const reader = new FileReader();
    reader.onload = ()=>{
      state.logoCustom = reader.result;
      state.logoChoice = 'custom';
      render();
      toast('Custom logo applied');
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };
});

// Sidebar tab switching
document.querySelectorAll('#sb-tabs button').forEach(btn=>{
  btn.onclick = ()=>{
    const panel = btn.dataset.panel;
    document.querySelectorAll('#sb-tabs button').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    document.querySelector('.sidebar-left').setAttribute('data-active', panel);
    document.querySelector('.sidebar-left').scrollTop = 0;
  };
});

// Re-layout canvas on window resize
let resizeTimer;
window.addEventListener('resize', ()=>{
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(renderCanvas, 100);
});

// Close modal on bg click
document.querySelectorAll('.modal-bg').forEach(m=>{
  m.addEventListener('click',(e)=>{
    if(e.target === m) m.classList.remove('open');
  });
});

// ============================================================
// INIT
// ============================================================
resetFieldsFromTemplate();
render();

// Expose for inline HTML handlers
window.closeModal = closeModal;

